        </>
      )}

      {stage.type === 'merge' && (
        <>
          <div className="space-y-1">
            <div className="flex items-center justify-between">
              <span className="text-[9px] font-bold uppercase text-text-muted tracking-wider block">
                Merge Stage (Git Operations Only)
              </span>
              <InfoTooltip
