	// eslint-disable-next-line security/detect-unsafe-regex -- bounded to 128 chars above, single optional fraction
	if (/^\d+(?:\.\d+)?$/.test(text)) {
		const ms = Number(text);
		if (!Number.isFinite(ms) || ms <= 0) return null;
		return Math.ceil(ms);
